#!/usr/bin/env python3
# HN Radiology Suite — Clinical Add-ons v2.16.0 safe installer
from pathlib import Path
import base64
import gzip
import re
import zipfile

VERSION = "2.16.0"
MARKER_START = "<!-- HN_CLINICAL_ADDONS_V216_START -->"
MARKER_END = "<!-- HN_CLINICAL_ADDONS_V216_END -->"

PAYLOAD_B64 = """"""

def main():
    root = Path(__file__).resolve().parents[2]
    index = root / "index.html"
    addon = gzip.decompress(base64.b64decode(PAYLOAD_B64)).decode("utf-8").strip()

    if not addon.startswith(MARKER_START) or not addon.endswith(MARKER_END):
        raise RuntimeError("Invalid add-on markers")

    html = index.read_text(encoding="utf-8")
    html = re.sub(re.escape(MARKER_START) + r".*?" + re.escape(MARKER_END), "", html, flags=re.S)
    pos = html.lower().rfind("</body>")
    if pos < 0:
        raise RuntimeError("index.html has no </body> tag")
    html = html[:pos] + "\n" + addon + "\n" + html[pos:]
    index.write_text(html, encoding="utf-8")

    required = [
        "HNClinicalAddonsV216",
        "9.54+1.482*x+0.1676*x*x",
        "8.96+0.540*x+0.0003*x*x*x",
        "Residual pregnancy tissue / RPOC",
        "Placenta Accreta Spectrum",
        "+ افزودن اسکار",
        "low-lying IUD",
    ]
    if html.count(MARKER_START) != 1 or html.count(MARKER_END) != 1:
        raise RuntimeError("Marker duplication")
    missing = [x for x in required if x not in html]
    if missing:
        raise RuntimeError("Missing validation markers: " + ", ".join(missing))

    out = root / "HN_Radiology_Suite_v2.16.0_CLINICAL_ADDONS_UPLOAD_READY.zip"
    with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
        for name in ["index.html", "twin-pregnancy.html", "styles.css", "README_START_FA.txt"]:
            p = root / name
            if p.exists():
                z.write(p, arcname=name)
        z.writestr(
            "CHANGES_v2.16.0_FA.txt",
            "HN Radiology Suite v2.16.0\n"
            "- Hadlock 1984 GA separately for BPD, HC, AC and FL.\n"
            "- Structured RPOC ultrasound block (gray-scale + Doppler).\n"
            "- PAS / placenta accreta gray-scale + Color Doppler checklist.\n"
            "- Repeatable Renal Scar items: side, site and optional residual parenchymal thickness.\n"
            "- IUD proper / low-lying / malposition options with optional fundal distance.\n"
        )
    print("Installed HN Clinical Add-ons v2.16.0")
    print("ZIP:", out.name)

if __name__ == "__main__":
    main()
